insert into public.hospitals (name, city, state, country, operational_status, medisync_tier, tier_basis, catalog_metadata) select 'Rajiv Gandhi Government General Hospital (Madras Medical College)', 'Chennai', 'Tamil Nadu', 'India', 'ACTIVE', 'Tier 1', 'By Hospital Type', jsonb_build_object('ownership','Government','district','Chennai','notes','Largest govt hospital in TN; major teaching hospital','source','Tamil_Nadu_Hospitals_3_Tier.xlsx') where not exists (select 1 from public.hospitals h where lower(h.name)=lower('Rajiv Gandhi Government General Hospital (Madras Medical College)') and lower(coalesce(h.city,''))=lower('Chennai'));
